entities.sql:
select w.country, sum(s.cost_eur) / count(distinct s.order_id) as avg_cost_per_order
from analytics.fct_shipments s join analytics.dim_warehouse w using (warehouse_id)
group by 1

with sold as (
  select p.category, sum(o.quantity) / 28.0 as daily_units
  from analytics.fct_orders_v2 o join analytics.dim_product p using (sku)
  where o.ordered_at >= now() - interval '28 days' group by 1),
stock as (
  select p.category, sum(i.on_hand_units) as on_hand
  from analytics.fct_inventory_snapshot i join analytics.dim_product p using (sku)
  where i.snapshot_date = (select max(snapshot_date) from analytics.fct_inventory_snapshot) group by 1)
select stock.category, on_hand / nullif(daily_units, 0) as days_of_cover
from stock left join sold using (category)

select p.category, sum(o.net_amount_eur) - sum(o.quantity * p.cost_price) as gross_margin_eur
from analytics.fct_orders_v2 o join analytics.dim_product p using (sku)
group by 1 order by 2 desc

select o.order_id, p.name, o.net_amount_eur / nullif(o.quantity, 0) as unit_price, p.cost_price
from analytics.fct_orders_v2 o join analytics.dim_product p using (sku)
where o.net_amount_eur / nullif(o.quantity, 0) < p.cost_price

select date_trunc('month', o.ordered_at) as month, sum(o.net_amount_eur) as revenue
from analytics.fct_orders_v2 o join analytics.dim_customer c using (customer_id)
where c.country = 'DE' group by 1 order by 1

select a.tier, sum(o.amount_eur) as open_value
from analytics.fct_wholesale_orders o join analytics.dim_wholesale_account a using (account_id)
where o.status in ('open', 'confirmed') group by 1

select p.category, sum(r.refund_amount) as refunded
from analytics.fct_returns r join analytics.fct_orders_v2 o using (order_line_id) join analytics.dim_product p using (sku)
group by 1 order by 2 desc

select w.name, avg(case when s.delivered_date <= s.promised_date then 1.0 else 0 end) as on_time_rate
from analytics.fct_shipments s join analytics.dim_warehouse w using (warehouse_id)
group by 1

select e.department, count(*) as headcount
from analytics.hr_employees e left join analytics.hr_terminations t using (employee_id)
where t.employee_id is null group by 1

select w.name, sum(i.on_hand_units) as on_hand
from analytics.fct_inventory_snapshot i join analytics.dim_warehouse w using (warehouse_id)
where i.snapshot_date = (select max(snapshot_date) from analytics.fct_inventory_snapshot) group by 1

select a.tier, sum(o.amount_eur) as revenue
from analytics.fct_wholesale_orders o join analytics.dim_wholesale_account a using (account_id)
where o.status = 'shipped' group by 1
